#include <cstdio>

int main() {
    int n = 0;
    if (std::scanf("%d", &n) != 1) return 1;
    if (n < 1 || n > 1000) return 1;
    int* items = new int[n];
    for (int i = 0; i < n; i++) {
        if (std::scanf("%d", &items[i]) != 1) {
            delete[] items;
            return 1;
        }
        if (items[i] < -100 || items[i] > 100) {
            delete[] items;
            return 1;
        }
    }
    long long total = 0;
    for (int i = 0; i < n; i++) {
        long long value = items[i];
        total += value * value;
    }
    delete[] items;
    std::printf("%lld\n", total);
    return 0;
}
